#!/bin/zsh
# 🪶️ The light proof of a TRIAL COPY of an asset of lane CL-T5 (`$GEN/try/<id>.json`), which must pass BEFORE the catalog file is written, one process after the other inside the grant of its caller: the triangle budgets of the copy as `🧊️model-catalog` counts them (`groups.ts`, must end in `BUDGET <id>: OK`), the GLB of its default pose with the live writer (`glb.ts`, at most 8 MiB, the budget of every pose GLB; with `GLB_GATE=0` the size is recorded and does not decide, for a tree whose remaining bytes are not its authored solids), the gate over every subject (`../MR/gate.ts --soft`), the gate over the poses alone as the scan line, the silhouette guard with `validateAsset` and the three-views sweep (`../MR/measure.ts`), the check CLI with `--file`. One line per check into `$GEN/light/<id>.txt`, ending in `LIGHT PROOF <id>: PASS|FAIL` with the digest of the copy. light2.sh <id>
source "${0:A:h}/env.sh"
a="$1"; f="$GEN/try/$a.json"; d="$GEN/light"; mkdir -p "$d"; ok=1; o="$d/$a.txt"; echo "light proof of $(date +%F\ %H:%M), copy sha-256 $(shasum -a 256 < "$f" | cut -c1-16)" > "$o"
(timeout 1800 zsh "$W/run.sh" groups.ts "$f" --top 6) > "$d/$a-budget.log" 2>&1; r=$?; grep -E "^$a (body|thermal|structure):|^  !|^BUDGET" "$d/$a-budget.log" | cut -c1-200 >> "$o"; [[ $r -eq 0 ]] && grep -q "^BUDGET $a: OK" "$d/$a-budget.log" || ok=0
(timeout 1800 zsh "$W/run.sh" glb.ts "$f") > "$d/$a-glb.log" 2>&1; r=$?; b=$(grep -m1 '^glb ' "$d/$a-glb.log" | awk '{print $2}'); echo "glb of the default pose: ${b:-?} bytes ($(( ${b:-0} / 10486 ))e-2 MiB, budget 8388608)" >> "$o"; [[ $r -eq 0 && -n "$b" ]] && [[ "$b" -le 8388608 || "${GLB_GATE:-1}" == 0 ]] || ok=0
(cd "$T" && timeout 3000 "$B" "$M/gate.ts" "$f" --soft) > "$d/$a-gate.log" 2>&1; r=$?; echo "gate exit $r $(tail -1 "$d/$a-gate.log" | cut -c1-200)" >> "$o"; [[ $r -eq 0 ]] || ok=0
(cd "$T" && timeout 3000 "$B" "$M/gate.ts" "$f" --poses) > "$d/$a-poses.log" 2>&1; r=$?; echo "scan (gate over the poses) exit $r $(tail -1 "$d/$a-poses.log" | cut -c1-200)" >> "$o"; [[ $r -eq 0 ]] || ok=0
(cd "$S/📦️packages/🟦️typescript" && timeout 2400 "$B" "$M/measure.ts" "$f") > "$d/$a-measure.log" 2>&1; r=$?; echo "measure exit $r" >> "$o"; grep -E "silhouette:|validate:|sweep:|bbox" "$d/$a-measure.log" | cut -c1-300 >> "$o"; grep '!' "$d/$a-measure.log" | cut -c1-300 >> "$o"
[[ $r -eq 0 ]] && grep -q "silhouette: OK" "$d/$a-measure.log" && grep -q "validate: 0 issues" "$d/$a-measure.log" && grep -q "sweep: 0 findings" "$d/$a-measure.log" || ok=0
(cd "$S" && timeout 2400 "$B" "🔨️modules/🗂️catalog/🩺️check/🟦️.ts" --file "$f") > "$d/$a-check.log" 2>&1; r=$?; echo "check: exit $r $(grep -m1 -E '^(✓|✗)' "$d/$a-check.log" | cut -c1-160)" >> "$o"; [[ $r -eq 0 ]] || ok=0
[[ $ok -eq 1 ]] && echo "LIGHT PROOF $a: PASS" >> "$o" || echo "LIGHT PROOF $a: FAIL" >> "$o"
